""" Converts a string of binary numbers to their two's compliment integer representation """
def convert_twos_compliment(bin_str: str) -> int {
    length = len(bin_str);
    if bin_str[0] == '0' {
        return int(bin_str, 2);
    }
    return int(bin_str, 2) - (1 << length);
}

"""Remove trailing zeroes in `t`."""
def rstrip_tuple(t: tuple[int, ...]) -> tuple[int, ...] {
    if not t or t[-1] {
        return t;
    }
    right = len(t) - 1;
    while right > 0 and t[right - 1] == 0 {
        right -= 1;
    }
    return t[0:right];
}

