"""
    Return modular inverse using a version Euclid's Algorithm
    Code by Andrew Kuchling in Python Journal:
    http://www.pythonjournal.com/volume1/issue1/art-algorithms/
    -- in turn also based on Knuth, vol 2.
    """
def invmod(a: int, b: int) -> int {
    (a1, a2, a3) = (1, 0, a);
    (b1, b2, b3) = (0, 1, b);
    while b3 != 0 {
        q = a3 / b3;
        t = (a1 - b1 * q, a2 - b2 * q, a3 - b3 * q);
        (a1, a2, a3) = (b1, b2, b3);
        (b1, b2, b3) = t;
    }
    while a2 < 0 {
        a2 = a2 + a;
    }
    return a2;
}

"""Calculates longest common subsequence length for a pair of tokenized strings."""
def my_lcs(string: list[str], sub: list[str]) -> int {
    if len(string) < len(sub) {
        (sub, string) = (string, sub);
    }
    lengths = [
        [0 for _ in range(len(sub) + 1)] for _ in range(len(string) + 1)
    ];
    for j in range(1, len(sub) + 1) {
        for i in range(1, len(string) + 1) {
            if string[i - 1] == sub[j - 1] {
                lengths[i][j] = lengths[i - 1][j - 1] + 1;
            } else {
                lengths[i][j] = max(lengths[i - 1][j], lengths[i][j - 1]);
            }
        }
    }
    return lengths[len(string)][len(sub)];
}

