"""[1,2,3,4,5,6,7]"""
def reorderOddEvent(nums: list[int]) -> list[int] {
    def event(num: int) -> bool {
        return num % 2 == 0;
    }
    (left_index, right_index) = (0, len(nums) - 1);
    while left_index < right_index {
        while left_index < right_index and not event(nums[left_index]) {
            left_index += 1;
        }
        while left_index < right_index and event(nums[right_index]) {
            right_index -= 1;
        }
        if left_index < right_index {
            (nums[left_index], nums[right_index]) = (nums[right_index], nums[left_index]);
        }
    }
    return nums;
}

"""Parse command line arguments into positional parameters, options and flags."""
def parse_arguments(arguments: list[str]) -> tuple[list[str], dict[str, str], list[str]] {
    positional_arguments = [];
    option_values = {};
    flag_values = [];
    for arg in arguments {
        if arg[0] != '-' {
            positional_arguments.append(arg);
        } elif '=' in arg {
            pair = arg.split('=');
            if pair[0][1] == '-' {
                option_values[pair[0][2:]] = pair[1];
            } else {
                option_values[pair[0][1]] = pair[1];
            }
        } elif arg[1] == '-' {
            flag_values.append(arg[2:]);
        } else {
            flag_values.append(arg[1:]);
        }
    }
    return (positional_arguments, option_values, flag_values);
}

"""Splits comma separated argument into size and rel attribute."""
def parse_args(args: str) -> tuple[str, str] {
    parts = args.split(",");
