}

"""Convert hexadecimal string to decimal integer."""
def hex2dec(inp: str, verbose: bool = True) -> int {
    out = 0;
    n = len(inp);
    for i in range(n)[::-1] {
        try {
            ch = str(inp[i].upper());
        } except Exception {
            ch = str(inp[i]);
        }
        digit: int;
        if ch == 'A' { digit = 10; }
        elif ch == 'B' { digit = 11; }
        elif ch == 'C' { digit = 12; }
        elif ch == 'D' { digit = 13; }
        elif ch == 'E' { digit = 14; }
        elif ch == 'F' { digit = 15; }
        elif ch != int(ch) {
            print('Invalid character **', ch, '**');
            return 0;
        } else {
            digit = int(ch);
        }
        out = out + digit * (16 ** (n - 1 - i));
    }
    if verbose { print(out); }
    return out;
}

"""Converts a sense hat pixel picture to SVG format.
pixels is a list of 64 smaller lists of [R, G, B] pixels."""
def render_svg(pixels: list[list[int]]) -> str {
    svg = '<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80">';
    for y in range(8) {
        for x in range(8) {
            color = pixels[(y * 8) + x];
            if color[0] == 0 and color[1] == 0 and color[2] == 0 {
                continue;
            }
            svg += '<rect x="{x}" y="{y}" width="10" height="10" style="fill:rgb({r},{g},{b})" />'.format(
                x=(x * 10), y=(y * 10), r=color[0], g=color[1], b=color[2]
            );
        }
    }
    svg += '</svg>';
    return svg;
}

