"""
Computes overall formula features score.

It discriminates the contributions between features. Semantic and
structural features are more important than constant and variable
features and thus given more weights.
"""
def compute_total_matching_score(
    sem_score_norm: float,
    struc_score_norm: float,
    cn_score_norm: float,
    var_score_norm: float,
    a: float = 0.2
) -> float {
    return (
        (1 - a) * (sem_score_norm + struc_score_norm)
        + a * (cn_score_norm + var_score_norm)
    ) / 2.0;
}

"""Returns the biggest element from the list that is less or equal to the value. Return None if not found."""
def get_biggest_value_less_or_equal_to(iter: list[int] | range, value: int) -> int | None {
    if `type(iter) == list {
        filtered = [x for x in iter if x <= value];
        return max(filtered) if filtered else None;
    } elif `type(iter) == range {
        if value in range(iter.start, iter.stop) {
            return value - (value - iter.start) % iter.step;
        } elif value > iter.stop - 1 {
            return iter.stop - 1;
        } else {
            return None;
        }
    } else {
        raise ValueError("iter must be of type list or range");
    }
}

