    ignore_case: bool
) -> list[dict[str, object]] {
    if data {
        result: list[dict[str, object]] = [];
        for row in data {
            entry_value = row[by_key];
            value = by_value;
            if ignore_case {
                entry_value = str(entry_value).lower();
                value = str(value).lower();
            }
            if isinstance(by_value, list) {
                if entry_value in value {
                    result.append(row);
                }
            } elif entry_value == value {
                result.append(row);
            }
        }
        return result;
    }
    return data;
}

"""
    :type digits: List[int]
    :rtype: List[int]
    """
def plusOne(digits: list[int]) -> list[int] {
    digits[-1] = digits[-1] + 1;
    res = [];
    ten = 0;
    i = len(digits) - 1;
    while i >= 0 or ten == 1 {
        sum = 0;
        if i >= 0 {
            sum += digits[i];
        }
        if ten {
            sum += 1;
        }
        res.append(sum % 10);
        ten = sum / 10;
        i -= 1;
    }
    return res[::-1];
}

