"""For a dictionary, makes a copy, to a depth of 3."""
def dictcopy3(lev1: object, depth: int = 3) -> object {
    if depth < 1 {
        return lev1;
    }
    try {
        lev2 = dict().fromkeys(lev1);
    } except Exception as e {
        return lev1;
    }
    try {
        for (k1, v1) in lev1.iteritems() {
            lev2[k1] = dictcopy3(v1, depth - 1);
        }
    } except Exception as e {
        return lev1;
    }
    return lev2;
}

"""
Reduces an NxN matrix over finite field Z/pZ.
"""
def reduce_matrix(M: list[list[int]], p: int, is_noise: bool = False) -> list[list[int]] {
    for (i, row) in enumerate(M) {
        for (j, element) in enumerate(row) {
            if is_noise and element < 0 and abs(element) < p {
                continue;
            }
            M[i][j] = element % p;
        }
    }
    return M;
}

