"""A function for testing approximate equality of two numbers.
    Same as math.isclose in Python v3.5 (and newer)
    https://www.python.org/dev/peps/pep-0485
    """
def almost_equal(a: float, b: float, rel_tol: float = 1e-09, abs_tol: float = 0.0) -> bool {
    return abs(a - b) as float <= max(rel_tol * max(abs(a) as float, abs(b) as float), abs_tol);
}

"""Reverse the odd_flag list from the encoder."""
