"""Edits two given strings and compare them."""
def backspace_compare(first: str, second: str) -> bool {
    first_index = len(first) - 1;
    second_index = len(second) - 1;
    skip_in_first = 0;
    skip_in_second = 0;
    while first_index >= 0 or second_index >= 0 {
        if first[first_index] == '#' {
            skip_in_first += 1;
            first_index -= 1;
            continue;
        } elif skip_in_first > 0 {
            first_index -= 1;
            skip_in_first -= 1;
            continue;
        }
        if second[second_index] == '#' {
            skip_in_second += 1;
            second_index -= 1;
            continue;
        } elif skip_in_second > 0 {
            second_index -= 1;
            skip_in_second -= 1;
            continue;
        }
        if (first_index >= 0 and second_index < 0) or (first_index < 0 and second_index >= 0) {
            return False;
        }
        if first[first_index] != second[second_index] {
            return False;
        }
        first_index -= 1;
        second_index -= 1;
    }
    return True;
}

"""Calculates coverage cost ratio for pathlet."""
def findCovCostRatio(
    trajStrajDist: dict[int, tuple[str | None, float]],
    c1: float,
    c3: float,
    strajCov: dict[str, int | float]
) -> int | float {
    (curCov, curCost) = (0, c1);
    for (k, v) in list(trajStrajDist.items()) {
        (straj, dist) = (v[0], v[1]);
        if straj is None {
            continue;
        }
        curCov += strajCov[straj];
        curCost += 1.0 * c3 * dist;
    }
    if curCov == 0 {
        return 0;
    }
    return 1.0 * curCov / (1.0 * curCost);
}

