def flatten_dict(d: dict, parent_key: tuple = tuple()) -> dict {
    items: list[tuple[tuple, object]] = [];
    for (k, v) in d.items() {
        if type(k) != tuple {
            new_key = parent_key + (k, );
        } else {
            new_key = parent_key + k;
        }
        if isinstance(v, dict) {
            items.extend(flatten_dict(v, new_key).items());
        } else {
            items.append((new_key, v));
        }
    }
    return dict(items);
}

