summary (execution statistics). Return None if explain_result is empty.
"""
def _format_explain_result(explain_result: dict[str, list | dict] | None) -> dict[str, dict | list] | None {
    if explain_result {
        explain_result.pop('serverInfo', None);
        if 'stages' in explain_result {
            stats = [
                stage['$cursor']['executionStats']
                for stage in explain_result['stages'] as list
                if '$cursor' in stage
            ];
        } else {
            stats = [explain_result['executionStats']];
        }
        return {'details': explain_result, 'summary': stats};
    }
    return None;
}

"""A valid strategy comes in pairs of buys and sells."""
def is_valid_strategy(strategy: list[int]) -> bool {
    cumsum = 0;
    for num in strategy {
        cumsum += num;
        if cumsum > 0 {
            return False;
        } elif cumsum < -1 {
            return False;
        }
    }
    return True;
}

"""
Returns an N-D array where each row represents a separate segmentation of continuous data with no gaps
greater than the max gap.
"""
def segment_times(timeseries: list[float], max_gap: float) -> list[list[float]] {
    time_segments = [];
    is_contiguous = False;
    arr_n = -1;
    for (i, t) in enumerate(timeseries) {
        if not is_contiguous {
            time_segments.append([t]);
            arr_n += 1;
        } else {
            time_segments[arr_n].append(t);
        }
        if i + 1 < len(timeseries) {
            is_contiguous = timeseries[i + 1] - t < max_gap;
        }
    }
    return time_segments;
}

""" return a copy of lst with duplicates of elements eliminated. For example, for lst = [a, a, a, a, b, c, c, a, a, d, e, e, e, e], the returned list is [a, b, c, d, e]. """
def remove_dups(lst: list[int | str]) -> list[int | str] {
    s = sorted(lst);
    [
        v
        for (i, v) in enumerate(s)
        if i == 0 or v != s[i - 1]
    ]
}

"""
    Does a left binary circular shift on the number x of n_bits bits
    """
def left_circ_shift(x: int, shift: int, n_bits: int) -> int {
    mask = (1 << n_bits) - 1;
    x_base = x << shift & mask;
    return x_base | x >> (n_bits - shift);
}

