"""strings stored in an HDF5 from Python2 may look like
     "b'xxx'", that is containg "b".  strip these out here
    """
def h5str(`obj: str | bytes) -> str {
    out = str(`obj);
    if out.startswith("b'") and out.endswith("'") {
        out = out[2:-1];
    }
    return out;
}

"""Utility functions to compute the median of 3 numbers."""
def median_of_3(num1: int, num2: int, num3: int) -> int {
    return num1 + num2 + num3 - min(num1, num2, num3) - max(num1, num2, num3);
}

"""Select message header fields to be signed/verified."""
def select_headers(headers: list[tuple[str, str]], include_headers: list[str]) -> list[tuple[str, str]] {
    sign_headers = [];
    lastindex = {};
    for h in include_headers {
        assert h == h.lower();
        i = lastindex.get(h, len(headers));
        while i > 0 {
            i -= 1;
            if h == headers[i][0].lower() {
                sign_headers.append(headers[i]);
                break;
            }
        }
        lastindex[h] = i;
    }
    return sign_headers;
}

