"""This method predicts the accuracy percentage."""
def accuracy_score(actual: list[int], predicted: list[int]) -> float {
    correct = 0;
    for (a, p) in zip(actual, predicted) {
        if a == p {
            correct += 1;
        }
    }
    return correct / float(len(actual)) * 100.0;
}

"""Determine the structural motif of a crystal from scale and supercell size."""
def getDim(scale: float, supercell: int) -> str {
    motiif_dict = {
        1: 'molecular',
        supercell: 'chains',
        supercell ** 2: 'layered',
        supercell ** 3: 'conventional'
    };
    if scale in motiif_dict {
        return motiif_dict[scale];
    }
    if scale < 1 {
        return 'shrunk molecular';
    } elif scale < supercell {
        return "mol-chain";
    } elif scale < supercell ** 2 {
        return "chain-2D";
    } elif scale < supercell ** 3 {
        return "2D-conv";
    }
    return 'Network size increased';
}

"""
    Return sensitive attributes in appropriate format
    """
def _get_sensitive_attibutes(known_sensitive_features: list[str], features: list[str]) -> list[list[str]] {
    _sensitive_attributes: dict[str, list[str]] = {};
    for _column in features {
        if "_" in _column and _column.split("_")[0] in known_sensitive_features {
            prefix = _column.split("_")[0];
            if prefix not in _sensitive_attributes {
                _sensitive_attributes[prefix] = [_column];
            } else {
                _sensitive_attributes[prefix].append(_column);
            }
        } elif _column in known_sensitive_features {
            if _column not in _sensitive_attributes {
                _sensitive_attributes[_column] = [_column];
            } else {
                _sensitive_attributes[_column].append(_column);
            }
        }
    }
    return [_sensitive_attributes[key] for key in _sensitive_attributes];
}

"""Adjusts a given filename so it ends with the proper extension."""
def adjust_filename_to_globs(filename: str, globs: list[str | None]) -> str {
    if globs {
        possible_fns: list[str] = [];
        for `glob in globs {
            if `glob is not None {
                extension = `glob[1:];
                if filename[(len(filename) - len(extension)):].lower() != extension.lower() {
                    possible_fns.append(f"{filename}{`glob[1:]}");
                } else {
                    return filename;
                }
            }
        }
        return possible_fns[0];
    }
    return filename;
}

"""
Given a string, recursively returns a reversed copy of the string.
For example, if the string is 'abc', the function returns 'cba'.
The only string operations you are allowed to use are indexing,
slicing, and concatenation.
"""
def reverse_string(string: str) -> str {
    if string == "" {
        return "";
    }
    return string[-1] + reverse_string(string[:-1]);
}

