"""Returns 1 if the two do not share a language, else 0"""
def sharedLangCost(criterion: dict[str, str], frRow: dict[str, str], exRow: dict[str, str]) -> int {
    fluentQ = criterion['fluentQ'];
    learningQ = criterion['learningQ'];
    frLangs = [set(frRow[fluentQ].split(',')), set(frRow[learningQ].split(','))];
    exLangs = [set(exRow[fluentQ].split(',')), set(exRow[learningQ].split(','))];
    return int(
        len(frLangs[0].union(frLangs[1]).intersection(exLangs[0].union(exLangs[1])))
        == 0
    );
}

"""Return a mapping from activity pairs to follow frequency at a given distance."""
def follows(trace: tuple, distance: int = 1) -> dict[tuple, int] {
    if not isinstance(trace, tuple) {
        raise ValueError("Trace has to be a tuple of activities.");
    }
    if not float(distance).is_integer() {
        raise ValueError("Distance has to be an integer.");
    }
    if not distance >= 1 {
        raise ValueError("Distance has to be greater or equal to 1.");
    }
    pairs = dict();
    for i in range(len(trace) - distance) {
        ai = trace[i];
        aj = trace[i + distance];
        if (ai, aj) not in pairs {
            pairs[(ai, aj)] = 0;
        }
        pairs[(ai, aj)] += 1;
    }
    return pairs;
}

"""Return left_x and width of overlapping x of two rects."""
def find_x_overlap(
    rect1: dict[str, int | float],
    rect2: dict[str, int | float]
) -> tuple[int | float, int | float] | None {
    r1left = rect1['left_x'];
    r1right = r1left + rect1['width'];
    r2left = rect2['left_x'];
    r2right = r2left + rect2['width'];
    highest_start_point = r1left if r1left >= r2left else r2left;
    lowest_end_point = r1right if r1right <= r2right else r2right;
    if highest_start_point < lowest_end_point {
        return (highest_start_point, lowest_end_point - highest_start_point);
    }
    return None;
}

