"""API data has duplicate transaction data. Clean it."""
def _remove_dups(elems: list[dict[str, str]], txids_seen: set[str]) -> list[dict[str, str]] {
    out = [];
    for elem in elems {
        txid = elem["txhash"];
        if txid in txids_seen {
            continue;
        }
        out.append(elem);
        txids_seen.add(txid);
    }
    return out;
}

"""Calculate the maximum symmetric quantized value according to number of bits."""
def calc_max_quant_value(bits: int) -> int {
    return (2 ** (bits - 1)) - 1;
}

"""Return the sensitivity based on the confusion matrix values."""
def calculateSensitivity(tn: int, fp: int, fn: int, tp: int) -> float {
    return tp / (tp + fn);
}

"""Format seconds as hours, minutes, and seconds."""
def timeFormat(time: int | float) -> str {
    time = int(time);
    seconds = time % 60;
    time = time // 60;
    minutes = time % 60;
    time = time // 60;
    hours = time % 60;
