"""Calculates hamming syndrom"""
def calculateHammingSyndrom(byte: list[int]) -> dict[str, int] {
    S0 = str(
        int(byte[1])
        ^ int(byte[3])
        ^ int(byte[5])
        ^ int(byte[7])
        ^ int(byte[9])
        ^ int(byte[11])
    );
    S1 = str(
        int(byte[2])
        ^ int(byte[3])
        ^ int(byte[6])
        ^ int(byte[7])
        ^ int(byte[10])
        ^ int(byte[11])
    );
    S2 = str(
        int(byte[4]) ^ int(byte[5]) ^ int(byte[6]) ^ int(byte[7]) ^ int(byte[12])
    );
    S3 = str(
        int(byte[8]) ^ int(byte[9]) ^ int(byte[10]) ^ int(byte[11]) ^ int(byte[12])
    );
    SX = str(
        int(byte[0])
        ^ int(byte[1])
        ^ int(byte[2])
        ^ int(byte[3])
        ^ int(byte[4])
        ^ int(byte[5])
        ^ int(byte[6])
        ^ int(byte[7])
        ^ int(byte[8])
        ^ int(byte[9])
        ^ int(byte[10])
        ^ int(byte[11])
        ^ int(byte[12])
    );
    S = int(S3 + S2 + S1 + S0, 2);
    return {"SX": int(SX), "S": S};
}

"""Generate a goal board with an given size

    Args:
        s (int, s>=3): The size of goal board to generate, i.e. the width of the board.

    Returns:
        goal (list): A 2D list representing tiles of the goal board,
                    e.g., if the size given is 3, the goal is [[1,2,3],[4,5,6],[7,8,9]].
    """
def make_goal(s: int) -> list[list[int]] {
    arr = [i for i in range(1, s * s)];
    arr.append(0);
    return [[arr[i * s + j] for j in range(s)] for i in range(s)];
}

