import re;

"""
    "(SO3)2" -> ("(SO3)2", "(SO3)", "2")
    "(SO3)" -> ("(SO3)", "(SO3)", "")
    """
def get_sub_formula(formula: str) -> tuple[str, str, str] | None {
    `match = re.search('(\([a-zA-Z\d]+\))(\d*)', formula);
    if not `match {
        return;
    }
    return (`match.group(0), `match.group(1), `match.group(2));
}

"""Add \ in front of * or _ so that Markdown doesn't interpret them."""
def protect_special_chars(lines: list[list[str]]) -> list[list[str]] {
    for (i, line) in enumerate(lines) {
        if line[0] in ('text', 'list', 'list-item') {
            protected_line = [];
            for c in line[1] {
                if c in '_*' {
                    protected_line.append('\\' + c);
                } else {
                    protected_line.append(c);
                }
            }
            lines[i][1] = ''.join(protected_line);
        }
    }
    return lines;
}

