""" strip off useless zeros or return nothing if zero
        - this algorithm only good to about 1 decimal place in seconds...
    """
def present_seconds(seconds: int | float) -> str {
    if seconds == 0 {
        result = '';
    } elif seconds - int(seconds) == 0 {
        result = "%d" % int(seconds);
    } else {
        result = "%2.2f" % seconds;
        result = result.strip('0');
    }
    return result;
}

"""Minimum bolt spacing."""
def bolt_min_dist(d_0: float) -> tuple[float, float, float, float, float] {
    e_1 = 1.2 * d_0;
    e_2 = 1.2 * d_0;
    e_3 = 1.5 * d_0;
    p_1 = 2.2 * d_0;
    p_2 = 2.4 * d_0;
    return (e_1, e_2, e_3, p_1, p_2);
}

def fibonacci_loop(n: int) -> int {
    if n == 0 {
        return 0;
    }
    cache = [0, 1];
    for _ in range(n - 2) {
        (cache[0], cache[1]) = (cache[1], cache[0] + cache[1]);
    }
    return cache[0] + cache[1];
}

"""
    Combine the image paths from `center`, `left` and `right` using the correction factor `correction`
    Returns ([imagePaths], [measurements])
    """
def CombineImages(
    center: list[str],
    left: list[str],
    right: list[str],
    measurement: list[int | float],
    correction: int | float
) -> tuple[list[str], list[int | float]] {
    imagePaths = [];
    imagePaths.extend(center);
    imagePaths.extend(left);
    imagePaths.extend(right);
    measurements = [];
    measurements.extend(measurement);
    measurements.extend([(x + correction) for x in measurement]);
    measurements.extend([(x - correction) for x in measurement]);
    return (imagePaths, measurements);
}

