"""Attempts to take the arguments in arg and kwargs and return only those which can be used
       by the argspec given."""
def conform_to_argspec(
    args: tuple[object, ...],
    kwargs: dict[str, object],
    argspec: tuple[list[str], str | None, str | None, tuple[object, ...] | None]
) -> tuple[list[object], dict[str, object]] {
    (regargs, varargs, varkwargs, defaults) = argspec;
    N = len(regargs);
    newargs = list(args);
    newkwargs = kwargs.copy();
    if varargs is None {
        newargs = newargs[:N];
    }
    for varname in regargs[len(newargs):] {
        try {
            newargs.append(newkwargs[varname]);
            del newkwargs[varname];
        } except KeyError {
            break;
        }
    }
    if varkwargs is None {
        newkwargs = {};
    }
    return (newargs, newkwargs);
}

"""
    Method to find the bottom center of every bbox

    Input:
        bboxes: all the boxes containing "person"

    Returns:
        Return a list of bottom center of every bbox
    """
def mid_point(bboxes: list[list[int]]) -> list[tuple[int, int]] {
    mid_values = list();
    for coor in bboxes {
        x1 = coor[0];
        y1 = coor[1];
        x2 = coor[2];
        y2 = coor[3];
        x_mid = int(x1 - ((x1 - (x1 + x2)) / 2));
        y_mid = int(y1 + y2);
        mid_values.append((x_mid, y_mid));
    }
    return mid_values;
}

""" Adds "0" as a suffix or prefix if it needs it. """
def add_zero(s: str, i: int) -> str {
    if "." in s and len(s.split(".")[1]) == 1 {
        return s + "0";
    }
    if i != 0 and len(s) == 4 {
        return "0" + s;
    }
    return s;
}

"""Return metadata filter as a dict with 'additional' and/or 'excluded' keys."""
def metadata_filter_as_dict(metadata_config: str | bool | dict[str, str | list[str]] | None) -> dict[str, str | list[str]] {
    if metadata_config is None {
        return {};
    }
    if metadata_config is True {
        return {'additional': 'all'};
    }
    if metadata_config is False {
        return {'excluded': 'all'};
    }
    if isinstance(metadata_config, dict) {
        assert set(metadata_config) <= set(['additional', 'excluded']);
        return metadata_config;
    }
    metadata_keys = metadata_config.split(',');
    metadata_config = {};
    for key in metadata_keys {
        key = key.strip();
        if key.startswith('-') {
            metadata_config.setdefault('excluded', []).append(key[1:].strip());
        } elif key.startswith('+') {
            metadata_config.setdefault('additional', []).append(key[1:].strip());
        } else {
            metadata_config.setdefault('additional', []).append(key);
        }
    }
    for section in metadata_config {
        if 'all' in metadata_config[section] {
            metadata_config[section] = 'all';
        } else {
            metadata_config[section] = [
                key
                for key in metadata_config[section]
                if key
            ];
        }
    }
    return metadata_config;
}

