"""
Function that finds a peak in a list of unsorted integers.

Args:
    list_of_integers (int): Unrdered integer list to find the peak

Returns:
    The peak value
"""
def find_peak(list_of_integers: list[int]) -> int | None {
    if len(list_of_integers) == 0 {
        return None;
    }
    if len(list_of_integers) == 1 {
        return list_of_integers[0];
    }
    if list_of_integers[1] <= list_of_integers[0] {
        return list_of_integers[0];
    }
    if list_of_integers[-1] >= list_of_integers[-2] {
        return list_of_integers[-1];
    }
    mid = len(list_of_integers) // 2;
    if list_of_integers[mid] >= list_of_integers[mid - 1]
        and list_of_integers[mid] >= list_of_integers[mid + 1] {
        return list_of_integers[mid];
    }
    if list_of_integers[mid + 1] > list_of_integers[mid] {
        return find_peak(list_of_integers[mid + 1:]);
    }
    if list_of_integers[mid - 1] > list_of_integers[mid] {
        return find_peak(list_of_integers[0:mid]);
    }
}

"""Returns list of running sums."""
def sum_values(values: list[int], period: int | None = None) -> list[int] {
    if period {
        if period < 1 {
            raise ValueError("period must be 1 or greater");
        }
        period = int(period);
    }
    results: list[int] = [];
    running_sum: int | None = None;
    for (idx, value) in enumerate(values) {
        if running_sum is None {
            running_sum = value;
        } elif not period or idx < period {
            running_sum += value;
        } else {
            old_value = values[idx - period];
            running_sum += value - old_value;
        }
        results.append(running_sum);
    }
    return results;
}

"""Formats the user input for a password policy."""
def format_properties(event: dict[str, dict[str, str | int | bool]]) -> dict[str, dict[str, str | int | bool]] {
    event_properties = event["ResourceProperties"];
    allowed_properties_bool = [
        "RequireSymbols",
        "RequireNumbers",
        "RequireUppercaseCharacters",
        "RequireLowercaseCharacters",
        "AllowUsersToChangePassword",
        "HardExpiry"
    ];
    for i in allowed_properties_bool {
        if event_properties[i] == "true" {
            event_properties[i] = True;
        } elif event_properties[i] == "false" {
            event_properties[i] = False;
        } else {
            raise Exception(
                "Resource property values not supported. Values must be boolean."
            );
        }
    }
    allowed_properties_int = [
        "MinimumPasswordLength",
        "MaxPasswordAge",
        "PasswordReusePrevention"
    ];
    for j in allowed_properties_int {
        event_properties[j] = int(event["ResourceProperties"][j] as str);
    }
    return event;
}

