"""
Create a basic sequence with the given pieces.

Keyword arguments:

piece_dict -- The pieces dictionary with the quantity of each piece.
"""
def basic_sequence(piece_dict: dict[str, int]) -> list[str] {
    sequence = [];
    for (piece, number) in piece_dict.items() {
        if number < 1 {
            continue;
        }
        times = ("%s " % piece) * number;
        sequence.extend(times.split());
    }
    return sequence;
}

"""Merge dicts by key."""
def merge_dict[V](this: dict[str, V], other: dict[str, V], cb: Callable[[V, V], V]) -> dict[str, V] {
    result = {};
    result.update(this);
    result.update(other);
    for key in this.keys() & other {
        result[key] = cb(this[key], other[key]);
    }
    return result;
}

