glob SECONDS_PER_DAY = 86400;
glob SECONDS_PER_HOUR = 3600;
glob SECONDS_PER_MINUTE = 60;

"""Format seconds timedelta to days, hours, minutes, seconds."""
def pretty_time_delta(seconds: int) -> str {
    sign_string = "-" if seconds < 0 else "";
    seconds = abs(int(seconds));
    (days, seconds) = divmod(seconds, SECONDS_PER_DAY);
    (hours, seconds) = divmod(seconds, SECONDS_PER_HOUR);
    (minutes, seconds) = divmod(seconds, SECONDS_PER_MINUTE);
    if days > 0 {
        return "%s%dd%dh%dm%ds" % (sign_string, days, hours, minutes, seconds);
    } elif hours > 0 {
        return "%s%dh%dm%ds" % (sign_string, hours, minutes, seconds);
    } elif minutes > 0 {
        return "%s%dm%ds" % (sign_string, minutes, seconds);
    } else {
        return "%s%ds" % (sign_string, seconds);
    }
}

