"""
    Parse a caching efficiency dictionary string into a dictionary.
    """
def convertJsonToDictionary(data: str) -> dict[str, list[int] | list[float] | list[str]] {
    output = {
        "#Payloads": [],
        "#queries": [],
        "#uniqueQueries": [],
        "PayloadSize (MB)": [],
        "folders": []
    };
    data = data.strip('{}');
    components = data.split(',"');
    folders_value = '';
    for comp in components[4:] {
        if folders_value {
            folders_value += ',"';
        }
        folders_value += comp;
    }
    components = components[:4] + [folders_value];
    for comp in components {
        elements = comp.split(':');
        (key, value) = (elements[0].strip('"'), elements[1].strip('[]'));
        if key == "folders" {
            value = value.split('","');
            for val in value {
                val = val.strip('"');
                output["folders"].append(val);
            }
        } else {
            value = value.split(',');
            if key == "PayloadSize (MB)" {
                output[key] = [float(val) for val in value];
            } else {
                output[key] = [int(val) for val in value];
            }
        }
    }
    return output;
}

