"""Update config keys from update, merging dicts and lists when merge is True."""
def update_config(
    config: dict[str, int | str | list | dict],
    update: dict[str, int | str | list | dict],
    merge: bool = True
) -> dict[str, int | str | list | dict] {
    result = {};
    for (key, value) in config.items() {
        if key in update and merge {
            if isinstance(value, dict) {
                result[key] = update_config(value, update[key]);
            } elif isinstance(value, list) {
                result[key] = value + update[key];
            } else {
                result[key] = update[key];
            }
        } elif key in update {
            result[key] = update[key];
        } else {
            result[key] = value;
        }
    }
    for (key, value) in update.items() {
        if key not in config {
            result[key] = value;
        }
    }
    return result;
}

"""
