    Input:
        topo        topology sequence of the protein
        begin_TM    sequence position at the beginning of the TM helix
                    (begin_TM, end_TM) defines the location of the TM helix
                    in the sequence
    Output:
        state       'i' or 'o', if all gaps, return empty string ""
    """
def Get_IOState_upstream(topo: str, begin_TM: int) -> str {
    i = begin_TM;
    while i >= 0 {
        if topo[i] in ('i', 'o') {
            return topo[i];
        }
        i -= 1;
    }
    return '';
}

"""
hsv: [h, s, v]
    h in [0, 360]
    s in [0, 1]
    v in [0, 1]
return [r, g, b]
    r, g, b in [0, 1]
"""
def hsv2rgb(hsv: list[float]) -> list[float] {
    h = hsv[0];
    s = hsv[1];
    v = hsv[2];
    hd = h / 60;
    r = v;
    g = v;
    b = v;
    if s > 0 {
        hdi = max(0, min(5, int(hd)));
        f = hd - hdi;
        if hdi == 0 {
            g *= 1 - s * (1 - f);
            b *= 1 - s;
        } elif hdi == 1 {
            r *= 1 - s * f;
            b *= 1 - s;
        } elif hdi == 2 {
            r *= 1 - s;
            b *= 1 - s * (1 - f);
        } elif hdi == 3 {
            r *= 1 - s;
            g *= 1 - s * f;
        } elif hdi == 4 {
            r *= 1 - s * (1 - f);
            g *= 1 - s;
        } elif hdi == 5 {
            g *= 1 - s;
            b *= 1 - s * f;
        }
    }
    return [r, g, b];
}

