"""Return the ascent set of a standard tableau (encoded as a sorted list)."""
def ascent_set(t: list[list[int]]) -> list[int] {
    row_locations: dict[int, int] = {};
    for (i, row) in enumerate(t) {
        for entry in row {
            row_locations[entry] = i;
        }
    }
    n = len(row_locations);
    if not n {
        return [];
    }
    ascents = [n];
    for i in range(1, n) {
        x = row_locations[i];
        u = row_locations[i + 1];
        if u <= x {
            ascents.append(i);
        }
    }
    return sorted(ascents);
}

"""Return True if ``d[k,j] = 0`` for ``0 <= k < i``

    Here ``d`` is a bit matrix implemented as an array of integers.
    """
def zero_column(d: list[int], j: int, i: int) -> bool {
    s = 0;
    for k in range(i) {
        s |= d[k];
    }
    return (s & (1 << j)) == 0;
}

