"""Returns the year, month, day of the next day. Simple version: assume every month has 30 days."""
def nextDay(year: int, month: int, day: int) -> tuple[int, int, int] {
    if day >= 30 {
        day = 1;
        month += 1;
    } else {
        day += 1;
    }
    if month > 12 {
        year += 1;
        month = 1;
    }
    return (year, month, day);
}

"""
Apply a format to a real value for writing out the data values.

This routine is used to format an input real value either in
exponential format or in floating point format depending on
the magnitude of the input value.
This works better for constant width columns than the Python g format.
"""
def strfmt(value: float) -> str {
    if abs(value) > 10000000.0 or abs(value) < 0.001 {
        outstring = '%14.7e ' % value;
        if value == 0.0 {
            outstring = '%14.6f ' % value;
        }
    } else {
        outstring = '%14.6f ' % value;
    }
    outstring = outstring.lstrip(' ');
    return outstring;
}

"""Solve quadratic equation."""
def delta(
    t1: float,
    tauv: float,
    taue: float,
    tauev: float,
    t0c: float,
    tzc: float,
    txc: float,
    dzi: float,
    dxi: float,
    dz2i: float,
    dx2i: float,
    vzero: float,
    vref: float,
    sgntz: float,
    sgntx: float
) -> float {
    ta = tauev + taue - tauv;
    tb = tauev - taue + tauv;
    apoly = dz2i + dx2i;
    bpoly = 4.0 * (sgntx * txc * dxi + sgntz * tzc * dzi) - 2.0 * (ta * dx2i + tb * dz2i);
    cpoly = ta ** 2.0 * dx2i + tb ** 2.0 * dz2i - 4.0 * (sgntx * txc * dxi * ta + sgntz * tzc * dzi * tb) + 4.0 * (vzero ** 2.0 - vref ** 2.0);
    dpoly = bpoly ** 2.0 - 4.0 * apoly * cpoly;
    return 0.5 * (dpoly ** 0.5 - bpoly) / apoly + t0c if dpoly >= 0.0 else t1;
}

