    if row % 2 != 0 {
        cols = range(ord("a"), ord("a") + 7, 2);
    } else {
        cols = range(ord("b"), ord("b") + 7, 2);
    }
    if ord(col) not in cols {
        return (-1, -1);
    }
    return (row, cols.index(ord(col)));
}

