"""Get the product of final horizontal position and depth after aim-adjusted commands."""
def get_correct_final_coordinates_product(commands: list[list[str | int]]) -> int {
    hor = 0;
    dep = 0;
    aim = 0;
    for com in commands {
        match com[0] {
            case "up":
                aim -= com[1];
            case "down":
                aim += com[1];
            case _:
                hor += com[1];
                dep += com[1] * aim;
        }
    }
    return hor * dep;
}

