"""Return the index of the first occurrence of value in lst, else -1."""
def linear_search(lst: list[int], value: int) -> int {
    i = 0;
    lst_length = len(lst);
    while i != lst_length and value != lst[i] {
        i += 1;
    }
    if i == lst_length {
        return -1;
    }
    return i;
}

def calc_max_num_clones(
    walker_weight: float, min_weight: float, max_num_walkers: int
) -> int {
    n_splits = 2;
    while (walker_weight / n_splits) >= min_weight and n_splits <= max_num_walkers {
        n_splits += 1;
    }
    n_splits -= 1;
    return n_splits - 1;
}

"""Get 'st', 'nd', 'rd' or 'th' as appropriate for an integer."""
def ordinal_suffix(i: int) -> str {
    if i < 0 {
        raise Exception("Can't handle negative numbers.");
    }
    if i % 100 in (11, 12, 13) {
        return 'th';
    } elif i % 10 is 1 {
        return 'st';
    } elif i % 10 is 2 {
        return 'nd';
    } elif i % 10 is 3 {
        return 'rd';
    } else {
        return 'th';
    }
}

