"""
Returns the size of a deeply nested object (dict/list/set).
The size of each leaf (non-dict/list/set) is 1.
"""
def objsize(`obj: dict[object, object] | list[object] | set[object]) -> int {
    assert isinstance(`obj, (dict, list, set)), `obj;
    if not `obj {
        return 0;
    }
    if isinstance(`obj, dict) {
        elem = next(iter(`obj.values()));
        if isinstance(elem, (dict, list, set)) {
            return sum(objsize(v) for v in `obj.values());
        }
        return len(`obj);
    }
    elem = next(iter(`obj));
    if isinstance(elem, (dict, list, set)) {
        return sum(objsize(v) for v in `obj);
    }
    return len(`obj);
}

"""
A regular flying circus happens twice or three times a month. For each month, information about the amount of money taken at each event is saved in a list, so that the amounts appear in the order in which they happened. The months' data is all collected in a dictionary called monthly_takings.

For this quiz, write a function total_takings that calculates the sum of takings from every circus in the year. Here's a sample input for this function:

monthly_takings = {'January': [54, 63], 'February': [64, 60], 'March': [63, 49],
                   'April': [57, 42], 'May': [55, 37], 'June': [34, 32],
                                      'July': [69, 41, 32], 'August': [40, 61, 40], 'September': [51, 62],
                                                         'October': [34, 58, 45], 'November': [67, 44], 'December': [41, 58]}
"""
def total_takings(monthly_takings: dict[str, list[int]]) -> int {
    sum_total_takings_in_year = 0;
    for key_month in monthly_takings {
        takings_in_month = monthly_takings[key_month];
        sum_takings_in_month = sum(takings_in_month);
        sum_total_takings_in_year += sum_takings_in_month;
    }
    return sum_total_takings_in_year;
}

"""Figures out if the given text has any unclosed ANSI sequences.

    It supports standard SGR (`\\x1b[1mHello`), OSC (`\\x1b[30;2ST\\x1b\\\\`) and Kitty APC codes
    (`\x1b_Garguments;hex_data\\x1b\\\\`). It also recognizes incorrect syntax; it only considers
    a tag closed when it is using the right closing sequence, e.g. `m` or `H` for SGR, `\\x1b\\\\`
    for OSC and APC types.

    Args:
        text: The text to test.

    Returns:
        True if there is at least one tag that hasn't been closed, False otherwise.
    """
def has_open_sequence(text: str) -> bool {
    is_osc = False;
    is_sgr = False;
    is_apc = False;
    open_count = 0;
    sequence = "";
    for char in text {
        if char == "\x1b" {
            open_count += 1;
            sequence += char;
            continue;
        }
        if len(sequence) == 0 {
            continue;
        }
        if char == "\\" and sequence[-1] == "\x1b" {
            open_count -= 1;
        }
        is_osc = is_osc or sequence[:2] == "\x1b]";
        is_sgr = is_sgr or sequence[:2] == "\x1b[";
        is_apc = is_apc or sequence[:3] == "\x1b_G";
        sequence += char;
        if (is_osc or is_apc) and sequence[-2:] == "\x1b\\" {
            sequence = "";
            open_count -= 1;
        } elif is_sgr and char in {"m", "H"} {
            sequence = "";
            open_count -= 1;
        }
    }
    return len(sequence) != 0 or open_count != 0;
}

"""Change a dictionary of kmer counts to a dictinary with kmer counts
    for a smaller value of k.
    """
def downsize_contextD(
    D: dict[str, list[int]],
    general_pattern: str,
    length: int | None
) -> tuple[dict[str, list[int]], str] {
    res: dict[str, list[int]] = {};
    start: int | None = None;
    end: int | None = None;
    for context in D {
        if start is None {
            assert length is not None;
            assert len(context) > length, f'k-mer:{context} cannot be reduced to length {length}';
            radius1 = len(context) // 2;
            radius2 = length // 2;
            start = radius1 - radius2;
            end = (radius1 - radius2) + length;
        }
        counts = D[context];
        context = context[start:end];
        if context not in res {
            res[context] = [0] * len(counts);
        }
        for i in range(len(counts)) {
            res[context][i] += counts[i];
        }
    }
    return (res, general_pattern[start:end]);
}

"""
This functions extracts the modified Behaviour Subsequence (BS) sequence list, which is the original sax word
sequence where every consecutive pairs of sax words are equal are fused into the same sax word.
"""
def extract_modified_bs_sequence(sax_sequence: list[str]) -> tuple[list[str], list[int]] {
    bs_sequence = [];
    bs_lengths = [];
    curr_len = 1;
    for i in range(len(sax_sequence)) {
        curr_bs = sax_sequence[i];
        next_bs = sax_sequence[i + 1] if i < len(sax_sequence) - 1 else '';
        if curr_bs == next_bs {
            curr_len = curr_len + 1;
        } else {
            bs_sequence.append(curr_bs);
            bs_lengths.append(curr_len);
            curr_len = 1;
        }
    }
    return (bs_sequence, bs_lengths);
}

