"""
    From a list of input objects ``objs`` get merged output object class.

    This is just taken as the deepest subclass. This doesn't handle complicated
    inheritance schemes.
    """
def _get_out_class[T](objs: list[T]) -> type {
    out_class = objs[0].__class__;
    for obj in objs[1:] {
        if issubclass(obj.__class__, out_class) {
            out_class = obj.__class__;
        }
    }
    if any(not issubclass(out_class, obj.__class__) for obj in objs) {
        raise ValueError(
            'unmergeable object classes {}'.format(
                [obj.__class__.__name__ for obj in objs]
            )
        );
    }
    return out_class;
}

"""Inverts age_to_eye_diameter

    Args:
         D_eye (float): Diameter of Eyepiece (mm); default is 7 mm
    Returns:
         age (float): approximate age
    """
def eye_to_age(D_eye: float) -> int {
    if D_eye > 7.25 {
        return 15;
    } elif D_eye <= 7.25 and D_eye > 6.75 {
        return 25;
    } elif D_eye <= 6.75 and D_eye > 6.25 {
        return 33;
    } elif D_eye <= 6.25 and D_eye > 5.75 {
        return 40;
    } elif D_eye <= 5.75 and D_eye > 5.25 {
        return 54;
    } else {
        return 70;
    }
}

"""
Given a param string and a dict of values, returns a flat dict of keyed, enumerated params.
Each dict in the values list must pertain to a single item and its data points.
"""
def enumerate_keyed_param(
    param: str,
    values: list[dict[str, str | int]] | dict[str, str | int] | tuple | set
) -> dict[str, str | int] {
    if not values {
        return {};
    }
    if not param.endswith('.') {
        param += '.';
    }
    if not isinstance(values, (list, tuple, set)) {
        values = [values];
    }
    for val in values {
        if not isinstance(val, dict) {
            raise ValueError(
                "Non-dict value detected. "
                "`values` must be a list, tuple, or set; containing only dicts."
            );
        }
    }
    params: dict[str, str | int] = {};
    for (idx, val_dict) in enumerate(values) {
        params.update(
            {
                '{param}{idx}.{key}'.format(param=param, idx=idx + 1, key=k): v
                for (k, v) in val_dict.items()
            }
        );
    }
    return params;
}

