    header_formatter: Callable[[str], str],
    formatter: Callable[[dict[str, str]], str],
    list_parser: Callable[[list[dict[str, str]], Callable[[dict[str, str]], str]], str],
    sorted_keys: list[str] | None = None
) -> str {
