"""flatten( sequence[, max_depth[, ltypes]] ) => sequence

    Flatten every sequence in "l" whose type is contained in "ltypes"
    to "max_depth" levels down the tree.  See the module documentation
    for a complete description of this function.

    The sequence returned has the same type as the input sequence.
    """
def flatten(l: list | tuple, max_depth: int | None = None, ltypes: tuple[type, type] | (lambda (x: list) -> bool) = (list, tuple)) -> list | tuple {
    if max_depth is None {
        make_flat = lambda (x: list) { True; };
    } else {
        make_flat = lambda (x: list) { max_depth > len(x); };
    }
    if callable(ltypes) {
        is_sequence = ltypes;
    } else {
        is_sequence = lambda (x: list | tuple) { isinstance(x, ltypes); };
    }
    r = list();
    s = list();
    s.append((0, l));
    while s {
        (i, l) = s.pop();
        while i < len(l) {
            while is_sequence(l[i]) {
                if not l[i] {
                    break;
                } elif make_flat(s) {
                    s.append((i + 1, l));
                    l = l[i];
                    i = 0;
                } else {
                    r.append(l[i]);
                    break;
                }
            } else {
                r.append(l[i]);
            }
            i += 1;
        }
    }
    try {
        return type(l)(r);
    } except TypeError {
        return r;
    }
}

"""Filler to list/array."""
def fill(instance: list[int | str | float | bool | None] | dict[int, int | str | float | bool | None], index: int, content: int | str | float | bool | None) {
    if isinstance(instance, list) {
        instance_len = len(instance);
        if instance_len == index or instance_len > index {
            instance[index] = content;
        }
        if instance_len == index - 1 {
            instance.append(content);
        }
        if instance_len < index {
            _n = index - instance_len;
            for _n_ in range(_n + 1) {
                instance.append(None);
            }
            instance[index] = content;
        }
        return;
    }
    if isinstance(instance, dict) {
        instance[index] = content;
        return;
    }
    raise TypeError("Instance need to be list");
}

"""Return euklidian distance between atoms coord1 and coord2."""
def euklid_dist(coord1: list[float], coord2: list[float]) -> float {
    xd2 = (coord1[0] - coord2[0]) ** 2;
    yd2 = (coord1[1] - coord2[1]) ** 2;
    zd2 = (coord1[2] - coord2[2]) ** 2;
    return (xd2 + yd2 + zd2) ** 0.5;
}

"""
    Square distance between point and a segment
    """
def getSquareSegmentDistance(
    p: tuple[float, float],
    p1: tuple[float, float],
    p2: tuple[float, float]
) -> float {
    x = p1[0];
    y = p1[1];
    dx = p2[0] - x;
    dy = p2[1] - y;
    if dx != 0 or dy != 0 {
        t = ((p[0] - x) * dx + (p[1] - y) * dy) / (dx * dx + dy * dy);
        if t > 1 {
            x = p2[0];
            y = p2[1];
        } elif t > 0 {
            x += dx * t;
            y += dy * t;
        }
    }
    dx = p[0] - x;
    dy = p[1] - y;
    return dx * dx + dy * dy;
}

