    num_frames_seg = stop_frame - start_frame + 1;
    changes = False;
    num_target_frames = min(num_target_frames, num_frames);
    if num_frames_seg < num_target_frames {
        while True {
            if start_frame > 0 {
                start_frame -= 1;
                num_frames_seg += 1;
                changes = True;
            }
            if num_frames_seg == num_target_frames {
                break;
            }
            if stop_frame < num_frames - 1 {
                stop_frame += 1;
                num_frames_seg += 1;
                changes = True;
            }
            if num_frames_seg == num_target_frames {
                break;
            }
        }
    }
    return start_frame, stop_frame, changes;
}

glob CRC32_POLY = 0xedb88320;
glob INT31_MASK = 0x7FFFFFFF;

"""Combine two CRC-32 checksums."""
def crc32_combine(crc1: int, crc2: int, len2: int) -> int {
    if len2 <= 0 {
        return crc1;
    }
    odd = [CRC32_POLY] + [1 << i for i in range(0, 31)];
    even = [0] * 32;
    def matrix_times(matrix: list[int], vector: int) -> int {
        number_sum = 0;
        matrix_index = 0;
        while vector != 0 {
            if vector & 1 {
                number_sum ^= matrix[matrix_index];
            }
            vector = (vector >> 1) & INT31_MASK;
            matrix_index += 1;
        }
        return number_sum;
    }
    even[:] = [matrix_times(odd, odd[n]) for n in range(0, 32)];
    odd[:] = [matrix_times(even, even[n]) for n in range(0, 32)];
    while len2 != 0 {
        even[:] = [matrix_times(odd, odd[n]) for n in range(0, 32)];
        if len2 & 1 {
            crc1 = matrix_times(even, crc1);
        }
        len2 >>= 1;
        if len2 == 0 {
            break;
        }
        odd[:] = [matrix_times(even, even[n]) for n in range(0, 32)];
        if len2 & 1 {
            crc1 = matrix_times(odd, crc1);
        }
        len2 >>= 1;
    }
    crc1 ^= crc2;
    return crc1;
}

"""Return the Levenshtein edit distance between two strings *a* and *b*."""
def levenshtein_distance(a: str, b: str) -> int {
    if a == b {
        return 0;
    }
    if len(a) < len(b) {
        (a, b) = (b, a);
    }
    if not a {
        return len(b);
    }
    previous_row = range(len(b) + 1);
    for (i, column1) in enumerate(a) {
        current_row = [i + 1];
        for (j, column2) in enumerate(b) {
            insertions = previous_row[j + 1] + 1;
            deletions = current_row[j] + 1;
            substitutions = previous_row[j] + (column1 != column2);
            current_row.append(min(insertions, deletions, substitutions));
        }
        previous_row = current_row;
    }
    return previous_row[-1];
}

"""Question 14.1: Compute the intersection of two sorted arrays."""
def compute_intersection(arr_1: list[int], arr_2: list[int]) -> list[int] {
    idx_1 = 0;
    idx_2 = 0;
    intersection = [];
    while idx_1 < len(arr_1) and idx_2 < len(arr_2) {
        if arr_1[idx_1] == arr_2[idx_2] {
            if not len(intersection) or arr_1[idx_1] != intersection[-1] {
                intersection.append(arr_1[idx_1]);
            }
            idx_1 += 1;
            idx_2 += 1;
        } elif arr_1[idx_1] < arr_2[idx_2] {
            idx_1 += 1;
        } else {
            idx_2 += 1;
        }
    }
    return intersection;
}

