"""Recursive quicksort"""
def rquicksort(arr: list[int]) -> list[int] {
    if len(arr) <= 1 {
        return arr;
    }
    return rquicksort([i for i in arr[1:] if i < arr[0]])
        + [arr[0]]
        + rquicksort([i for i in arr[1:] if i > arr[0]]);
}

import operator;
import itertools;

"""Return the contiguous job ids in the given list.

    Returns
    -------
    contiguous_job_ids : str
        The job ids organized in contiguous sets.

    """
def find_contiguous_ids(job_ids: list[int]) -> str {
    contiguous_job_ids = [];
    for (k, g) in itertools.groupby(
        enumerate(job_ids), lambda (x: tuple[int, int]) { x[0] - x[1] }
    ) {
        group = list(map(operator.itemgetter(1), g));
        if len(group) == 1 {
            contiguous_job_ids.append(str(group[0]));
        } else {
            contiguous_job_ids.append('{}-{}'.format(group[0], group[-1]));
        }
    }
    return ','.join(contiguous_job_ids);
}

"""Convert a declination string to degrees."""
def PDMS2Dec(decst: str, sep: str = ":") -> float {
    pp = decst.split(sep);
    if len(pp) > 0 {
        deg = int(pp[0]);
    } else {
        deg = 0;
    }
    if len(pp) > 1 {
        min = int(pp[1]);
    } else {
        min = 0;
    }
    if len(pp) > 2 {
        ssec = float(pp[2]);
    } else {
        ssec = 0.0;
    }
    dec = float(abs(deg)) + (float(min) / 60.0) + (ssec / 3600.0);
    if pp[0].find("-") >= 0 {
        dec = -dec;
    }
    return dec;
}

"""Calculate the address class of the IP address based on bits of binary string."""
def getAddressClass(binaryString: str) -> str {
    addressClass = "";
    if binaryString[0] == "0" {
