"""Return merged, sorted array and number of split inversions."""
def _merge_and_count_split_inv(left: list[int], right: list[int]) -> tuple[list[int], int] {
    max_left = len(left);
    max_right = len(right);
    if max_left == 0 or max_right == 0 {
        return left + right, 0;
    }
    merged: list[int] = [];
    inv_count = 0;
    i = 0;
    j = 0;
    while i < max_left and j < max_right {
        if left[i] <= right[j] {
            merged.append(left[i]);
            i += 1;
        } else {
            merged.append(right[j]);
            j += 1;
            inv_count += max_left - i;
        }
    }
    while i < max_left {
        merged.append(left[i]);
        i += 1;
    }
    while j < max_right {
        merged.append(right[j]);
        j += 1;
    }
    return merged, inv_count;
}

"""Return a tuple containing (host, port) of a string possibly
    containing both.  If there is no port in host_port, the port
    will be None.

    Supports the following:
    - hostnames
    - ipv4 addresses
    - ipv6 addresses
    with or without ports.  There is no validation of either the
    host or port.

    """
def split_host_port(host_port: str) -> tuple[str, str | None] | list[str] {
    colon_count = host_port.count(':');
    match colon_count {
        case 0:
            return (host_port, None);
        case 1:
            return host_port.split(':', 1);
        case _ if colon_count >= 2:
            if ']:' in host_port {
                parts = host_port.split(']:', 1);
                host = parts[0] as str;
                port = parts[1] as str;
                if host[0] == '[' {
                    host = host[1:];
                }
                return (host, port);
            }
            host = host_port as str;
            if host[0] == '[' {
                host = host[1:];
            }
            if host[-1] == ']' {
                host = host[:-1];
            }
            return (host, None);
    }
}

