"""Internal Numba implementation of the Lempel-Ziv (LZ) complexity."""
def _lz_complexity(binary_string: list[int]) -> int {
    complexity = 1;
    prefix_len = 1;
    len_substring = 1;
    max_len_substring = 1;
    pointer = 0;
    while prefix_len + len_substring <= len(binary_string) {
        if binary_string[pointer + len_substring - 1] == binary_string[prefix_len + len_substring - 1] {
            len_substring += 1;
        } else {
            max_len_substring = max(len_substring, max_len_substring);
            pointer += 1;
            if pointer == prefix_len {
                complexity += 1;
                prefix_len += max_len_substring;
                pointer = 0;
                max_len_substring = 1;
            }
            len_substring = 1;
        }
    }
    if len_substring != 1 {
        complexity += 1;
    }
    return complexity;
}

"""Next power of two for a given input, with a minimum of 16 and a maximum of 512."""
def next_pow_two(max_sent_tokens: int) -> int {
    pow_two = [16, 32, 64, 128, 256, 512];
    if max_sent_tokens <= pow_two[0] {
        return pow_two[0];
    }
    if max_sent_tokens >= pow_two[-1] {
        return pow_two[-1];
    }
    idx = [max_sent_tokens > j for j in pow_two].index(False);
    return pow_two[idx];
}

