"""
Taken from https://gist.github.com/meyerjo/dd3533edc97c81258898f60d8978eddc
both boxes should be in format [x1, y1, x2, y2]
"""
def bb_intersection_over_union(
    boxA: list[float], boxB: list[float], if_return_areas: bool = False
) -> float | tuple[float, tuple[float, float, float]] {
    xA = max(boxA[0], boxB[0]);
    yA = max(boxA[1], boxB[1]);
    xB = min(boxA[2], boxB[2]);
    yB = min(boxA[3], boxB[3]);
    inter_area = abs(max(xB - xA, 0) * max(yB - yA, 0));
    box_a_area = abs((boxA[2] - boxA[0]) * (boxA[3] - boxA[1]));
    box_b_area = abs((boxB[2] - boxB[0]) * (boxB[3] - boxB[1]));
    iou = inter_area / float(box_a_area + box_b_area - inter_area);
    if not if_return_areas {
        return iou;
    }
    return (iou, (inter_area, box_a_area, box_b_area));
}

