floor would be a decimal value, e.g. 0.05
"""
def reldiff(x: float, y: float, floor: float | None = None) -> float | int {
    d = x - y;
    if not d {
        return 0;
    }
    ref = x or y;
    d = float(d) / ref;
    return d if not floor else (0, d)[abs(d) >= floor];
}

"""
    >>> parse_file_string("File 123: ABC (X, Y) Z")
    ('ABC (X, Y) Z', '')
    >>> parse_file_string("File 123: ABC (X) Y (Z)")
    ('ABC (X) Y', 'Z')
    >>> parse_file_string("File: ABC")
    ('ABC', '')
    >>> parse_file_string("File 2: A, B, 1-2")
    ('A, B, 1-2', '')
    """
def parse_file_string(filestring: str) -> tuple[str, str] {
    if filestring.strip()[-1] != ")" {
        filestring = filestring.strip() + "()";
    }
    if ':' in filestring {
        rhs = filestring.partition(":")[2];
    } else {
        rhs = filestring;
    }
    chunks = rhs.split('(');
    indname = '('.join(chunks[:-1]);
    units = chunks[-1].replace(')', '');
    return (indname.strip(), units.strip());
}

