"""Make sure no illegal characters are contained in the file name."""
def normpath(pathname: str) -> str {
    import from sys { platform }
    illegal_chars = ":?*";
    for c in illegal_chars {
        if platform == "win32" and c == ":" and pathname[1:2] == ":" {
            pathname = pathname[0:2] + pathname[2:].replace(c, "");
        } else {
            pathname = pathname.replace(c, ".");
        }
    }
    return pathname;
}

"""Computes the average translation and rotation within a sequence (across subsequences of diff lengths)."""
def getStats(err: list[list[float]]) -> tuple[float, float] {
    t_err = 0;
    r_err = 0;
    for e in err {
        t_err += e[2];
        r_err += e[1];
    }
    t_err /= float(len(err));
    r_err /= float(len(err));
    return (t_err, r_err);
}

