def find_profile(profiles: dict[str, list[list[int]]], chrom: str, start_bp: int, end_bp: int) -> list[int] | None {
    if chrom in profiles {
        for el in profiles[chrom] {
            if el[0] == start_bp and el[1] == end_bp {
                return [el[2], el[3]];
            }
        }
    }
    return None;
}

"""clojure.core/update for Python's stateful maps."""
def update[V](m: dict[str, V], k: str, f: Callable[[V], V], *args: object, **kwargs: object) -> dict[str, V] {
    if k in m {
        m[k] = f(m[k], *args, **kwargs);
    }
    return m;
}
